//! Basic geometric types mirroring the Clipper2 public interface.

/// 64-bit integer point.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub fn new(x: i64, y: i64) -> Self {
        Point64 { x, y }
    }
}

/// A single polygon contour.
pub type Path64 = Vec<Point64>;

/// A set of polygon contours.
pub type Paths64 = Vec<Path64>;

/// Fill rule used when resolving polygon self-overlap. Kept for interface
/// parity with the C++ API; the boolean engine below operates on simple
/// contours where the choice does not affect the result.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FillRule {
    EvenOdd,
    NonZero,
    Positive,
    Negative,
}

