//! Low-level geometric predicates used by the boolean engine.

pub type FPoint = (f64, f64);

/// Even-odd point-in-polygon test (ray casting).
pub fn point_in_polygon(pt: FPoint, poly: &[FPoint]) -> bool {
    let n = poly.len();
    if n < 3 {
        return false;
    }
    let mut inside = false;
    let mut j = n - 1;
    for i in 0..n {
        let (xi, yi) = poly[i];
        let (xj, yj) = poly[j];
        if (yi > pt.1) != (yj > pt.1) && pt.0 < (xj - xi) * (pt.1 - yi) / (yj - yi) + xi {
            inside = !inside;
        }
        j = i;
    }
    inside
}

/// Intersection of segments p1->p2 and p3->p4.
/// Returns `Some((t, u))` where the intersection point is
/// `p1 + t * (p2 - p1)` and `p3 + u * (p4 - p3)`, or `None` when the
/// segments are parallel or do not cross within their extents.
pub fn seg_intersect(p1: FPoint, p2: FPoint, p3: FPoint, p4: FPoint) -> Option<(f64, f64)> {
    let d1x = p2.0 - p1.0;
    let d1y = p2.1 - p1.1;
    let d2x = p4.0 - p3.0;
    let d2y = p4.1 - p3.1;
    let denom = d1x * d2y - d1y * d2x;
    if denom.abs() < 1e-12 {
        return None;
    }
    let t = ((p3.0 - p1.0) * d2y - (p3.1 - p1.1) * d2x) / denom;
    let u = ((p3.0 - p1.0) * d1y - (p3.1 - p1.1) * d1x) / denom;
    if (-1e-9..=1.0 + 1e-9).contains(&t) && (-1e-9..=1.0 + 1e-9).contains(&u) {
        Some((t, u))
    } else {
        None
    }
}

