    intersect: bool,
    entry: bool,
    visited: bool,
    neighbor: usize, // index of the matching crossing in the other list
}

fn to_fpoints(path: &Path64) -> Vec<FPoint> {
    path.iter().map(|p| (p.x as f64, p.y as f64)).collect()
}

fn to_path(poly: Vec<FPoint>) -> Path64 {
    let mut out: Path64 = Vec::with_capacity(poly.len());
    for (x, y) in poly {
        let p = Point64::new(x.round() as i64, y.round() as i64);
        if out.last() != Some(&p) {
            out.push(p);
        }
    }
    if out.len() > 1 && out.first() == out.last() {
        out.pop();
    }
    out
}

/// Build both vertex rings with every proper edge crossing inserted.
/// Returns `None` when the two polygons share no proper crossings.
fn build_rings(subject: &[FPoint], clip: &[FPoint]) -> Option<(Vec<Node>, Vec<Node>)> {
    let ns = subject.len();
    let nc = clip.len();

    // Per-edge hit lists: (param along own edge, x, y, other edge, id).
    let mut s_hits: Vec<Vec<(f64, f64, f64, usize, usize)>> = vec![Vec::new(); ns];
    let mut c_hits: Vec<Vec<(f64, f64, f64, usize, usize)>> = vec![Vec::new(); nc];
    let mut next_id = 0usize;

    for i in 0..ns {
        let (p1, p2) = (subject[i], subject[(i + 1) % ns]);
        for j in 0..nc {
            let (q1, q2) = (clip[j], clip[(j + 1) % nc]);
            if let Some((t, u)) = seg_intersect(p1, p2, q1, q2) {
                // Only proper crossings (strictly inside both edges).
                if t > 1e-9 && t < 1.0 - 1e-9 && u > 1e-9 && u < 1.0 - 1e-9 {
                    let x = p1.0 + t * (p2.0 - p1.0);
                    let y = p1.1 + t * (p2.1 - p1.1);
                    s_hits[i].push((t, x, y, j, next_id));
                    c_hits[j].push((u, x, y, i, next_id));
                    next_id += 1;
                }
            }
        }
    }
    if next_id == 0 {
        return None;
    }

    for h in s_hits.iter_mut() {
        h.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
    }
    for h in c_hits.iter_mut() {
        h.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
    }

    // Rebuild rings, inserting crossings in edge order.
    let mut s_nodes: Vec<Node> = Vec::new();
    let mut s_index_of: Vec<Vec<usize>> = vec![Vec::new(); ns]; // per edge, node idx per hit id order
    for i in 0..ns {
        s_nodes.push(Node {
            x: subject[i].0,
            y: subject[i].1,
            next: 0,
            prev: 0,
            intersect: false,
            entry: false,
            visited: false,
            neighbor: usize::MAX,
        });
        for hit in &s_hits[i] {
            s_index_of[i].push(s_nodes.len());
            s_nodes.push(Node {
                x: hit.1,
                y: hit.2,
                next: 0,
                prev: 0,
                intersect: true,
                entry: false,
                visited: false,
                neighbor: usize::MAX,
            });
        }
    }
    let m = s_nodes.len();
    for i in 0..m {
        s_nodes[i].next = (i + 1) % m;
        s_nodes[i].prev = (i + m - 1) % m;
    }

    let mut c_nodes: Vec<Node> = Vec::new();
    let mut c_index_of: Vec<Vec<usize>> = vec![Vec::new(); nc];
    for j in 0..nc {
        c_nodes.push(Node {
            x: clip[j].0,
            y: clip[j].1,
            next: 0,
            prev: 0,
            intersect: false,
            entry: false,
            visited: false,
            neighbor: usize::MAX,
        });
        for hit in &c_hits[j] {
            c_index_of[j].push(c_nodes.len());
            c_nodes.push(Node {
                x: hit.1,
                y: hit.2,
                next: 0,
                prev: 0,
                intersect: true,
                entry: false,
                visited: false,
                neighbor: usize::MAX,
            });
        }
    }
    let k = c_nodes.len();
    for j in 0..k {
        c_nodes[j].next = (j + 1) % k;
        c_nodes[j].prev = (j + k - 1) % k;
    }

    // Link neighbors by shared intersection id.
    for i in 0..ns {
        for (ord, hit) in s_hits[i].iter().enumerate() {
            let (j, id) = (hit.3, hit.4);
            let cord = c_hits[j]
                .iter()
                .position(|h| h.4 == id)
                .expect("matching crossing");
            let si = s_index_of[i][ord];
            let ci = c_index_of[j][cord];
            s_nodes[si].neighbor = ci;
            c_nodes[ci].neighbor = si;
        }
    }

    Some((s_nodes, c_nodes))
}

/// Assign entry/exit flags to every crossing, walking the ring in order.
fn mark_entries(nodes: &mut [Node], start_inside: bool) {
    let mut entry = !start_inside;
    for node in nodes.iter_mut() {
        if node.intersect {
            node.entry = entry;
            entry = !entry;
        }
    }
}

/// Trace result contours over two rings whose entry/exit flags are set.
fn trace(s_nodes: &mut [Node], c_nodes: &mut [Node]) -> Vec<Vec<FPoint>> {
    let mut out: Vec<Vec<FPoint>> = Vec::new();
    for start in 0..s_nodes.len() {
        if !s_nodes[start].intersect || s_nodes[start].visited {
            continue;
        }
        let mut poly: Vec<FPoint> = Vec::new();
        let mut in_subject = true;
        let mut cur = start;
        loop {
            // Mark this crossing (and its twin) visited.
            let (entry, step_next, step_prev) = if in_subject {
                let nb = s_nodes[cur].neighbor;
                s_nodes[cur].visited = true;
                c_nodes[nb].visited = true;
                (s_nodes[cur].entry, s_nodes[cur].next, s_nodes[cur].prev)
            } else {
                let nb = c_nodes[cur].neighbor;
                c_nodes[cur].visited = true;
                s_nodes[nb].visited = true;
                (c_nodes[cur].entry, c_nodes[cur].next, c_nodes[cur].prev)
            };

            // Walk along the current ring until the next crossing.
            let mut idx = if entry { step_next } else { step_prev };
            loop {
                let (x, y, is_cross, nxt, prv) = if in_subject {
                    let n = &s_nodes[idx];
                    (n.x, n.y, n.intersect, n.next, n.prev)
                } else {
                    let n = &c_nodes[idx];
                    (n.x, n.y, n.intersect, n.next, n.prev)
                };
                poly.push((x, y));
                if is_cross {
                    break;
                }
                idx = if entry { nxt } else { prv };
            }

            // Hop to the other ring at this crossing.
            let neighbor = if in_subject {
                s_nodes[idx].neighbor
            } else {
                c_nodes[idx].neighbor
            };
            cur = neighbor;
            in_subject = !in_subject;

            let done = if in_subject {
                s_nodes[cur].visited
            } else {
                c_nodes[cur].visited
            };
            if done {
                break;
            }
        }
        if poly.len() > 1 && poly.first() == poly.last() {
            poly.pop();
        }
        if poly.len() >= 3 {
            out.push(poly);
        }
    }
    out
}

/// Boolean operation between a single subject path and a single clip path.
fn clip_pair(subject: &Path64, clip: &Path64, op: ClipType) -> Paths64 {
    let s = to_fpoints(subject);
    let c = to_fpoints(clip);

    let rings = build_rings(&s, &c);
    let (mut s_nodes, mut c_nodes) = match rings {
        Some(r) => r,
        None => {
            // No proper crossings: containment or disjointness.
            let s_in_c = point_in_polygon(s[0], &c);
            let c_in_s = point_in_polygon(c[0], &s);
            return match op {
                ClipType::Intersection => {
                    if s_in_c {
                        vec![subject.clone()]
                    } else if c_in_s {
                        vec![clip.clone()]
                    } else {
                        Vec::new()
                    }
                }
                ClipType::Union => {
                    if s_in_c {
                        vec![clip.clone()]
                    } else if c_in_s {
                        vec![subject.clone()]
                    } else {
                        vec![subject.clone(), clip.clone()]
                    }
                }
                ClipType::Difference => {
                    if s_in_c {
                        Vec::new()
                    } else {
                        vec![subject.clone()]
                    }
                }
                ClipType::Xor => unreachable!(),
            };
        }
    };

    mark_entries(&mut s_nodes, point_in_polygon(s[0], &c));
    mark_entries(&mut c_nodes, point_in_polygon(c[0], &s));

    match op {
        ClipType::Intersection => {}
        ClipType::Union => {
            for n in s_nodes.iter_mut().chain(c_nodes.iter_mut()) {
                if n.intersect {
                    n.entry = !n.entry;
                }
            }
        }
        ClipType::Difference => {
            for n in c_nodes.iter_mut() {
                if n.intersect {
                    n.entry = !n.entry;
                }
            }
        }
        ClipType::Xor => unreachable!(),
    }

    trace(&mut s_nodes, &mut c_nodes)
        .into_iter()
        .map(to_path)
        .collect()
}

/// Generic entry point mirroring `Clipper2Lib::BooleanOp`.
pub fn boolean_op(
    clip_type: ClipType,
    subjects: &Paths64,
    clips: &Paths64,
    _fill_rule: FillRule,
) -> Paths64 {
    match clip_type {
        ClipType::Intersection => {
            let mut out = Vec::new();
            for s in subjects {
                let mut acc = vec![s.clone()];
                for c in clips {
                    let mut next = Vec::new();
                    for a in &acc {
                        next.extend(clip_pair(a, c, ClipType::Intersection));
                    }
                    acc = next;
                }
                out.extend(acc);
            }
            out
        }
        ClipType::Union => {
            let mut acc: Paths64 = Vec::new();
            for p in subjects.iter().chain(clips.iter()) {
                if acc.is_empty() {
                    acc.push(p.clone());
                } else {
                    let mut next = Vec::new();
                    for a in &acc {
                        next.extend(clip_pair(a, p, ClipType::Union));
                    }
                    acc = next;
                }
            }
            acc
        }
        ClipType::Difference => {
            let mut out = Vec::new();
            for s in subjects {
                let mut acc = vec![s.clone()];
                for c in clips {
                    let mut next = Vec::new();
                    for a in &acc {
                        next.extend(clip_pair(a, c, ClipType::Difference));
                    }
                    acc = next;
                }
                out.extend(acc);
            }
            out
        }
        ClipType::Xor => {
            // A ^ B = (A \ B) + (B \ A); the two regions are disjoint.
            let mut out = boolean_op(ClipType::Difference, subjects, clips, _fill_rule);
            out.extend(boolean_op(ClipType::Difference, clips, subjects, _fill_rule));
            out
        }
    }
}

/// Mirrors `Clipper2Lib::Intersect`.
pub fn intersect(subjects: &Paths64, clips: &Paths64, fill_rule: FillRule) -> Paths64 {
    boolean_op(ClipType::Intersection, subjects, clips, fill_rule)
}

/// Mirrors `Clipper2Lib::Union`.
pub fn union(subjects: &Paths64, clips: &Paths64, fill_rule: FillRule) -> Paths64 {
    boolean_op(ClipType::Union, subjects, clips, fill_rule)
}

/// Mirrors `Clipper2Lib::Difference`.
pub fn difference(subjects: &Paths64, clips: &Paths64, fill_rule: FillRule) -> Paths64 {
    boolean_op(ClipType::Difference, subjects, clips, fill_rule)
}

/// Mirrors `Clipper2Lib::Xor`.
pub fn xor(subjects: &Paths64, clips: &Paths64, fill_rule: FillRule) -> Paths64 {
    boolean_op(ClipType::Xor, subjects, clips, fill_rule)
}

