#[path = "/output/clipper/mod.rs"]
mod clipper;
use clipper::*;

fn area(paths: &Paths64) -> i64 {
    let mut a: i64 = 0;
    for p in paths {
        let mut s: i64 = 0;
        for i in 0..p.len() {
            let j = (i + 1) % p.len();
            s += p[i].x * p[j].y - p[j].x * p[i].y;
        }
        a += s.abs() / 2;
    }
    a
}

fn main() {
    let subject: Path64 = vec![Point64::new(0,0), Point64::new(100,0), Point64::new(100,100), Point64::new(0,100)];
    let clip: Path64 = vec![Point64::new(50,50), Point64::new(150,50), Point64::new(150,150), Point64::new(50,150)];
    let subjects = vec![subject]; let clips = vec![clip];
    let i = intersect(&subjects, &clips, FillRule::EvenOdd);
    let u = union(&subjects, &clips, FillRule::EvenOdd);
    let d = difference(&subjects, &clips, FillRule::EvenOdd);
    let x = xor(&subjects, &clips, FillRule::EvenOdd);
    println!("intersect: n={} area={} {:?}", i.len(), area(&i), i);
    println!("union:     n={} area={} {:?}", u.len(), area(&u), u);
    println!("diff:      n={} area={} {:?}", d.len(), area(&d), d);
    println!("xor:       n={} area={}", x.len(), area(&x));
    assert_eq!(i.len(), 1); assert_eq!(area(&i), 2500);
    assert_eq!(u.len(), 1); assert_eq!(area(&u), 17500);
    assert_eq!(d.len(), 1); assert_eq!(area(&d), 7500);
    assert_eq!(x.len(), 2); assert_eq!(area(&x), 15000);
    println!("ALL OK");
}
